package com.productionhouse.crm.legal.contracts.api;
import com.productionhouse.crm.legal.contracts.dto.*;import com.productionhouse.crm.legal.contracts.service.ContractRecordService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/legal/contracts") public class ContractRecordController{private final ContractRecordService service;public ContractRecordController(ContractRecordService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('CONTRACT_READ')") public Page<ContractResponse> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String projectRef,@RequestParam(required=false)String contractType,@RequestParam(required=false)LocalDate expiresBefore,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return service.list(q,status,projectRef,contractType,expiresBefore,page,size,sort,direction);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('CONTRACT_READ')") public ContractResponse get(@PathVariable Long id){return service.get(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('CONTRACT_WRITE')") public ContractResponse create(@Valid @RequestBody ContractRequest request){return service.create(request);}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('CONTRACT_WRITE')") public ContractResponse update(@PathVariable Long id,@Valid @RequestBody ContractRequest request){return service.update(id,request);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority('CONTRACT_DELETE')") public void delete(@PathVariable Long id){service.delete(id);}}
